def transform2(grid):
    h,w=len(grid),len(grid[0]); seen=set(); objects=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and (r,c) not in seen:
                stack=[(r,c)]; seen.add((r,c)); cells=[]
                while stack:
                    x,y=stack.pop(); cells.append((x,y))
                    for dx in (-1,0,1):
                        for dy in (-1,0,1):
                            if dx==dy==0: continue
                            nx,ny=x+dx,y+dy
                            if 0<=nx<h and 0<=ny<w and grid[nx][ny] != 0 and (nx,ny) not in seen:
                                seen.add((nx,ny)); stack.append((nx,ny))
                objects.append(cells)
    masks=[]
    for cells in objects:
        r0=min(r for r,c in cells); r1=max(r for r,c in cells); c0=min(c for r,c in cells); c1=max(c for r,c in cells)
        pts=set(cells)
        mask=[[grid[r][c] if (r,c) in pts else 0 for c in range(c0,c1+1)] for r in range(r0,r1+1)]
        masks.append(mask)
    odd=[m for m in masks if any(row != row[::-1] for row in m)]
    assert len(odd)==1, [m for m in masks]
    return odd[0]
